/* IS EVERY COMMITTED THUMBNAIL STILL THE ART CAM DREW? 2026-08-24.
 *
 * assets/bh/thumb/{192,384} is GENERATED from the masters in assets/bh/<slot>/
 * by scripts/build-bh-thumbs.py, and it is generated BY HAND. Redraw a master,
 * commit it, forget the script, and every tiled surface in the app keeps
 * serving the old artwork: the Collection's cells, the crew card figure and
 * backdrop, the stacked avatar layers. Nothing throws, nothing looks broken,
 * and the only way to see it is to look at two pictures side by side.
 *
 * Found on 2026-08-24, and it had already happened twice, in both directions:
 *
 *   STALE   GS1, GS2, GS3, IL9, IL10-1, IL10-2, IL17-1 and IL17-2 were showing
 *           superseded art at both tiers. IL9 differed on 24.6% of the tile.
 *   MISSING C6, the 50,000-coin legendary pet, had no square thumbnail at all,
 *           and this one SHIPPED VISIBLY. The Collection's grid (js/app.js, the
 *           `looks` tab) iterates BH_SLOTS, which ends in C, so a player who
 *           owns Bumbleseal gets a tile whose src is bhThumb(bhAsset(C6)).
 *           That <img> carries no THUMB_FALLBACK onerror, unlike every layer
 *           avatarLayersHtml emits, so it cannot degrade to the master.
 *           Measured in a real browser on e2cb252d, account owning C6, the
 *           Collection open with 363 cells rendered: 404 on
 *           assets/bh/thumb/192/C/C6.png, naturalWidth 0, and the cell drew
 *           Chrome's broken-image icon over the alt text "Bumbleseal".
 *           An earlier draft of this file claimed the opposite, that no
 *           surface could ask for a C6 tier. That was wrong, it was reasoned
 *           from the avatar stack alone, and it took a review to catch.
 *
 * So this is the class, not the eight instances: regenerate every tier IN
 * MEMORY and compare it to what is committed. The comparison lives in the
 * generator itself (`--check`), because a second implementation of the resize
 * is a second thing to drift.
 *
 * CONTROL is not optional here and it is not a comment: this file builds a
 * three-file tree with one deliberately wrong thumbnail and one deliberately
 * absent one, runs the real checker against it, and FAILS unless the checker
 * names both. A green FRESH row beside a blind checker is exactly the shape
 * guard-hygiene-lint.mjs exists to catch.
 *
 * It cannot see the 640px masters themselves, or any tier the app adds later
 * without telling the generator. Saying so rather than implying it covers art.
 *
 * PROVEN RED three ways, each in its own cp -R copy of the tree, each reddening
 * exactly the rows it should:
 *   1. the sixteen thumbnails restored to their pre-fix bytes and C6's two
 *      deleted, i.e. main on 2026-08-24  -> FRESH alone, naming all 18
 *   0. 'C' dropped from the generator's SLOTS and C6's tiles corrupted, the
 *      mutation the first draft could NOT see  -> PARITY alone
 *   2. `box = diff.getbbox()` -> `box = None`  -> CONTROL-stale alone
 *   3. the missing.append() line removed    -> CONTROL-missing alone
 */
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, copyFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, '..');
const gen = join(repo, 'scripts', 'build-bh-thumbs.py');

const fails = [];
const ok = (n, pass, d = '') => { console.log(`${pass ? 'ok  ' : 'FAIL'}  ${n}${d ? '  ' + d : ''}`); if (!pass) fails.push(n); };

function check(...args) {
  try {
    return { code: 0, out: execFileSync('python3', [gen, '--check', ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }) };
  } catch (e) {
    if (e.code === 'ENOENT') return { code: -1, out: 'python3 not on PATH' };
    return { code: e.status, out: `${e.stdout || ''}${e.stderr || ''}` };
  }
}

/* ---- THE REAL TREE ------------------------------------------------------ */
const real = check();
ok('SETUP the checker ran at all (a missing python3 or Pillow must FAIL, never skip)',
  real.code >= 0 && /checked \d+ committed thumbnails/.test(real.out),
  real.out.split('\n')[0] || 'no output');

const checked = Number((real.out.match(/checked (\d+) committed/) || [])[1] || 0);
ok('SAMPLE the checker examined the whole sheet, not a corner of it',
  checked >= 1000, `${checked} thumbnails compared against a fresh render of their masters`);

const bad = real.out.split('\n').filter(l => /^(STALE|MISSING)/.test(l));
ok('FRESH every committed thumbnail is what the generator makes from today\'s master',
  real.code === 0 && bad.length === 0,
  bad.length ? `${bad.length} drifted: ${bad.slice(0, 6).join(' | ')}  -> run python3 scripts/build-bh-thumbs.py`
             : `${checked} fresh`);

/* ---- THE ENUMERATION ITSELF --------------------------------------------- */
/* THE HOLE A REVIEWER FOUND IN THE FIRST DRAFT, 2026-08-24. check() and build()
   share one walk, so a slot deleted from the generator's SLOTS list stops being
   BUILT and stops being CHECKED in lockstep, and the lint says clean. Proven:
   with 'C' removed and C6's tiles overwritten with IL9's art -- this branch's
   own bug, reintroduced -- the lint printed `clean` and exited 0. The only
   thing standing in the way was SAMPLE's threshold, which had 40 files of
   slack on a 740 sheet, enough to hide six of the fifteen slots.

   js/app.js's BH_THUMB_RE is the app's half of the same list, and its comment
   claims "the regex mirrors the generator's KEEP rule exactly", which nothing
   checked. Now something does, and it is the useful direction too: a slot the
   app serves that the generator does not build is a 404 on every item in it. */
const genSrc = readFileSync(gen, 'utf8');
const appSrc = readFileSync(join(repo, 'js', 'app.js'), 'utf8');
const genSlots = (genSrc.match(/^SLOTS = \[([^\]]*)\]/m) || [])[1];
const appSlots = (appSrc.match(/const BH_THUMB_RE = \/\^assets\\\/bh\\\/\(\(\?:([^)]*)\)/) || [])[1];
const norm = t => (t || '').replace(/['\s]/g, '').split(/[,|]/).filter(Boolean).sort().join(' ');
ok('PARITY the generator builds exactly the slots js/app.js serves a tier for',
  !!genSlots && !!appSlots && norm(genSlots) === norm(appSlots),
  !genSlots || !appSlots
    ? 'could not read one of the two lists, so this row proved NOTHING'
    : norm(genSlots) === norm(appSlots)
      ? `${norm(appSlots).split(' ').length} slots, both lists agree`
      : `generator [${norm(genSlots)}] vs js/app.js BH_THUMB_RE [${norm(appSlots)}]`);

/* ---- THE POSITIVE CONTROL ----------------------------------------------- */
/* A tree with GS1's master, IL9's thumbnail filed under GS1's name at 192, and
   nothing at all at 384. Both defects are plain file copies, so this control
   needs no image library of its own and cannot itself be subtly wrong. */
const tmp = mkdtempSync(join(tmpdir(), 'thumbfresh-'));
try {
  mkdirSync(join(tmp, 'assets', 'bh', 'G'), { recursive: true });
  mkdirSync(join(tmp, 'assets', 'bh', 'thumb', '192', 'G'), { recursive: true });
  copyFileSync(join(repo, 'assets/bh/G/GS1.png'), join(tmp, 'assets/bh/G/GS1.png'));
  copyFileSync(join(repo, 'assets/bh/thumb/192/IL/IL9.png'), join(tmp, 'assets/bh/thumb/192/G/GS1.png'));
  const ctl = check('--root', tmp);
  ok('CONTROL the checker sees a thumbnail whose pixels are not its master\'s',
    ctl.code === 1 && /^STALE\s+thumb\/192\/G\/GS1\.png/m.test(ctl.out),
    (ctl.out.match(/^STALE.*/m) || ['no STALE row: this checker is blind and every row above it is worthless'])[0]);
  ok('CONTROL the checker sees a tier that is missing from disk',
    ctl.code === 1 && /^MISSING\s+thumb\/384\/G\/GS1\.png/m.test(ctl.out),
    (ctl.out.match(/^MISSING.*/m) || ['no MISSING row: C6\'s bug could ship again unseen'])[0]);
} finally {
  rmSync(tmp, { recursive: true, force: true });
}

console.log(fails.length ? `\nthumb freshness: ${fails.length} FAILED` : '\nthumb freshness: clean');
process.exit(fails.length ? 1 : 0);
